CREATE TABLE clinical.emergency_access_records ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES clinical.patients (id) ON DELETE CASCADE, clinician_id uuid NOT NULL REFERENCES clinical.clinicians (id), scope clinical.consent_scope NOT NULL, reason text NOT NULL, granted_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz, revoked_reason text, recorded_by uuid NOT NULL REFERENCES identity.users (id), CONSTRAINT emergency_expiry_after_grant CHECK (expires_at > granted_at), CONSTRAINT emergency_revoked_after_grant CHECK (revoked_at IS NULL OR revoked_at >= granted_at) ); CREATE INDEX idx_emergency_access_patient ON clinical.emergency_access_records (patient_id, clinician_id, expires_at DESC);